import { examples } from './examples.js';
import { agentExample } from './agent-example.js';

export const pages = [
  ['','Getting started','Start here'],
  ['agents','Working with agents','Start here'],
  ['language','Language basics','Start here'],
  ['interface','Interface and state','Build an app'],
  ['functions','Functions and types','Build an app'],
  ['data','Resources and mutations','Build an app'],
  ['server','Database and server','Build an app'],
  ['testing','Testing','Develop and ship'],
  ['tooling','Diagnostics and tooling','Develop and ship'],
  ['output','Build and run','Develop and ship'],
  ['reference','Language reference','Reference'],
  ['about','Status and limits','Reference'],
];
const href = slug => '/docs' + (slug ? '/' + slug : '');
const p = text => `<p>${text}</p>`;
const list = items => `<ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>`;
const inline = text => `<code>${text}</code>`;
const section = (id,title,body) => ({id,title,body});
export function articles(code) {
  return {
    '': {
      intro:'Build and run your first GRHM application from the source checkout. Then give your coding agent the language reference and a checked edit workflow.',
      sections:[
        section('requirements','Before you start', p('GRHM requires Node 22.13 or newer; use Node 22.22 or later on the 22 release line, or Node 24.15 or later, so the generated TypeScript runs without experimental flags. You also need npm and a local copy of the GRHM repository.')),
        section('install','Build the compiler', p('Run these commands from the repository root. The build creates the compiler and CLI in <code>dist/</code>.') + code('npm install\nnpm run build','terminal')),
        section('create','Create an application', p('Create a project inside the checkout. Point its GRHM dependency at the parent directory so it uses the compiler you just built.') + code("node dist/cli.js new my-app\ncd my-app\nnpm pkg set 'devDependencies.@ashxsf/grhm=file:..'\nnpm install\nnpm run dev",'terminal') + p('Open the local address printed by the development server. Edit <code>app.grhm</code>; the compiler watches the project and updates the browser.')),
        section('first-page','Write your first page', p('Replace <code>app.grhm</code> with this complete application. <code>state</code> stores a value, and <code>set</code> changes it when a button is clicked.') + code(examples[0].source)),
        section('project','Find your way around', table([['File','Purpose'],['app.grhm','Your application source'],['grhm.json','Entry file and generated output directory'],['src/gen/','Generated React, TypeScript, and CSS'],['vite.config.ts','Development server and build configuration']]) + p('Keep your edits in the source files. A later compilation replaces the generated files. Continue with <a href="/docs/language">language basics</a> or explore a <a href="/examples">complete example</a>.')),
      ]
    },
    agents: {
      intro:'GRHM gives coding agents a compact application format, a schema-generated reference, and a compiler protocol for inspecting, editing, and checking their work.',
      sections:[
        section('context','Give the agent the language', p('Start with a local project from <a href="/docs">getting started</a>. Run the reference command and provide its output to your coding agent. The operation signatures come from the compiler’s schema, so the reference follows the implementation.') + code('npx grhm reference\nnpx grhm check --json','terminal') + p('The program describes interface, state, functions, and server behavior. The compiler generates framework wiring. Short aliases such as <code>v</code>, <code>txt</code>, and <code>btn</code> keep source compact; descriptive aliases represent the same program.')),
        section('instructions','A starting instruction for your agent', p('Give the agent your task, the local project, and these working instructions. Use an agent that can read files and run terminal commands.') + code('Work in the GRHM source files.\nRead `npx grhm reference` for the language vocabulary.\nRun `npx grhm check --json` before changing the project.\nUse `npx grhm inspect --node <id> --json` to inspect a target.\nFor structural edits, use a patch with the current revision.\nIf a patch is stale, read the current source before retrying.\nUse diagnostic codes and suggestions to repair errors.\nAdd tests for the requested behavior. Build the app, run\nTypeScript and the available tests, then inspect it in a browser.\nReport what changed and which checks actually ran.','Agent instructions')),
        section('inspect','Inspect a stable target', p('This complete example names the grid <code>product-grid</code>. Save it as <code>app.grhm</code> in a scaffolded project to follow along. The agent can inspect that subtree without relying on a line number.') + code(agentExample.source) + code('npx grhm inspect --node product-grid --json\nnpx grhm check --json','terminal') + p('Inspection returns the node, its parent context, and its source file. IDs derive from semantic keys and survive formatting and unrelated edits. Assign explicit <code>:id</code> values to frequent patch targets: unnamed same-operation siblings can otherwise shift occurrence-based IDs.')),
        section('patch','Describe and validate the change', p('To change the grid from four columns to three, the agent targets one node and sets one property. This patch uses the revision of the exact example above; for your project, use the revision returned by the latest check.') + code(agentExample.patch,'change.grhm') + code('npx grhm patch change.grhm --json','terminal') + p('The compiler validates the entire patched project before writing changed files. This is the response produced for the example:') + code(JSON.stringify(agentExample.result,null,2),'patch result.json') + p('The resulting source keeps the same explicit target:') + code(agentExample.after) + p('Revisions hash canonical source across all included files. Formatting alone does not change a revision. Replaying this patch after the edit produces <code>E504</code>, a revision conflict. An invalid patch result is also rejected; either rejection leaves source unchanged.')),
        section('repair','Repair from structured feedback', p('The agent can read a stable diagnostic code and affected field instead of interpreting a terminal message. For example, <code>:colr</code> is an unknown property:') + code(agentExample.broken) + p('This excerpt comes from the compiler’s diagnostic for that source:') + code(JSON.stringify(Object.fromEntries(['schema','code','severity','nodeId','op','field','suggestions'].map(key=>[key,agentExample.diagnostic[key]])),null,2),'diagnostic excerpt.json') + p('The agent has a target (<code>greeting</code>), a field (<code>colr</code>), and a suggested spelling (<code>:color</code>). The full record also includes a source span, message, and expected properties. Available fields vary by diagnostic. Run the checker again after making a repair.')),
        section('verify','Check the behavior as well as the source', p('Compiler validation catches invalid forms, unresolved names, route mismatches, and known type errors. A valid program can still do the wrong thing. Add <a href="/docs/testing">behavior tests</a> and inspect the running application.') + code('npx grhm check --json\nnpx grhm fmt --check\nnpx grhm build\nnpx tsc --noEmit\nnpx grhm test','terminal') + p('The Vite build does not run TypeScript checking. Run it explicitly. Check the test output for skipped runners; install Playwright and its browser as described in the testing guide to run browser tests. Opaque JavaScript imports and external payloads also need checks beyond GRHM’s inferred types.')),
        section('tools','Connect through a persistent compiler process', p('For tool integrations, <code>grhm serve</code> accepts JSON lines on standard input. The same process supports checking, inspection, patching, compilation, and reference generation. A patch preview validates without writing.') + code('npx grhm serve','terminal') + code('{"id":1,"method":"check"}\n{"id":2,"method":"inspect","params":{"node":"product-grid"}}\n'+JSON.stringify({id:3,method:'patch',params:{patch:agentExample.patch,preview:true}}),'JSON-lines requests') + p('Replace the sample patch revision with the current one before sending the third request. The SDK and LSP share the project implementation; see <a href="/docs/tooling">diagnostics and tooling</a> for editor support.')),
      ]
    },
    language: {
      intro:'GRHM uses nested forms to describe an application. The same small syntax covers interface declarations and expressions.',
      sections:[
        section('forms','Forms and values', p('A form starts with an operation, followed by its arguments. Parentheses define nesting. Strings use double quotes; comments begin with a semicolon and end at the next line.') + code('; A value-producing expression\n(+ 2 3)\n\n; An element with a property\n(txt "Hello" :size 24)','forms.grhm') + p('Values include strings, numbers, <code>true</code>, <code>false</code>, and <code>null</code>. Identifiers use kebab-case. A colon introduces a keyword property, such as <code>:gap</code>.')),
        section('structure','Application structure', p('A program has one <code>app</code> declaration. Pages, state, components, functions, and server declarations belong inside it. A <code>tests</code> block can sit inside or alongside the application.') + code('(app hello\n  (page "/" home\n    (heading "Hello")))')),
        section('names','Names and aliases', p('Short and descriptive forms have the same meaning: <code>v</code> and <code>vstack</code>, <code>txt</code> and <code>text</code>, <code>btn</code> and <code>button</code>. Formatting can project between them without changing the program’s node IDs.') + code('npx grhm fmt --descriptive\nnpx grhm fmt --compact','terminal')),
        section('expressions','Expressions and declarations', p('Expressions produce values. Declarations define application structure. Actions such as <code>set</code>, <code>nav</code>, and <code>send</code> run inside events.') + code('(btn "Continue"\n  (click (nav "/next")))','event.grhm') + p('The checker validates references and types before the compiler writes output. An invalid program emits diagnostics and no generated files.')),
        section('files','Split a project into files', p('Use <code>include</code> to bring in other source files. Paths resolve relative to the including file. The compiler detects include cycles and assigns IDs across the whole project.') + code('(include "components.grhm")\n(include "pages/catalog.grhm")','includes.grhm')),
      ]
    },
    interface: {
      intro:'Compose pages from layouts, content, and reusable components. State connects those elements to user actions.',
      sections:[
        section('layout','Layout and content', p('<code>v</code> stacks children vertically; <code>h</code> arranges them horizontally. Use <code>grid</code> for columns, <code>card</code> for a grouped surface, and <code>scroll</code> for a scrolling region.') + code('(v :pad 32 :gap 24\n  (heading "Your library")\n  (grid :cols 3 :cols-sm 1 :gap 16\n    (card (txt "The Little Schemer"))\n    (card (txt "Structure and Interpretation"))))','layout.grhm')),
        section('state','State and local values', p('<code>state</code> belongs to the application and is shared between pages. <code>local</code> belongs to a page or component instance. Initial values determine their inferred types. Both can hold function values.') + code('(state count 0)\n\n(page "/" home\n  (local name "")\n  (v :gap 12\n    (input :value name :label "Your name")\n    (txt "Hello, " name)\n    (btn "Add one"\n      (click (set count (+ count 1))))))','state.grhm')),
        section('components','Components and props', p('Declare the values a component accepts with <code>props</code>. Action props let the parent decide what an interaction does. A <code>slot</code> renders children supplied by the caller.') + code('(component book\n  (props (title string) (on-open action))\n  (card :gap 12\n    (heading title)\n    (btn "Open" (click on-open))))\n\n; Inside a page\n(book :title "The Little Schemer"\n  :on-open (nav "/books/1"))','component.grhm')),
        section('routing','Pages and navigation', p('Pages use history routing. Parameters in braces bind as strings. Use <code>path</code> to build a URL with encoded parameters, and <code>:title</code> to set the document title.') + code('(page "/books/{id}" detail :title (concat "Book " id)\n  (heading "Book " id))\n\n; In an event\n(nav (path "/books/{id}" :id 1))','routing.grhm')),
        section('styling','Tokens, breakpoints, and motion', p('Theme tokens are referenced with <code>$</code>. Responsive properties use <code>-sm</code> and <code>-md</code> suffixes. Motion properties respect reduced-motion preferences.') + code('(theme\n  (token primary "#426b38")\n  (dark (token primary "#d3f5a2")))\n\n(v :bg $primary :pad 32 :pad-sm 16 :enter fade-up\n  (heading "Hello"))','theme.grhm') + p('The <a href="/docs/reference#styles">style reference</a> lists supported properties. Built-in widgets include dialogs with focus trapping, tabs, menus, forms, tables, and file inputs.')),
      ]
    },
    functions: {
      intro:'Write reusable logic with pure functions, collections, and records. The compiler shares these functions between the client and server.',
      sections:[
        section('functions','Define and call a function', p('Functions can be recursive and first-class. Parameter types are optional; available annotations include base types and declared table names.') + code('(fn square ((x number))\n  (* x x))\n\n(fn total-squares (items)\n  (sum (map square items)))\n\n; Returns 14\n(total-squares (arr 1 2 3))','functions.grhm') + p('Function bodies see their parameters, other functions, and imports. They do not read application state or resources.')),
        section('collections','Collections and local bindings', p('<code>arr</code> creates a list. Use <code>map</code>, <code>filter</code>, <code>reduce</code>, and <code>sort-by</code> to transform it. A lambda defines a function inline. Bindings inside <code>let</code> are evaluated in order.') + code('(let ((prices (arr 12 24 36))\n      (discount 0.8))\n  (map (lambda (price) (* price discount)) prices))','collections.grhm')),
        section('records','Records and inference', p('Create records with <code>obj</code> and read fields with dotted access or <code>get</code>. Inference tracks record fields, list elements, function results, nullable values, and table rows.') + code('(let ((book (obj :title "The Little Schemer" :pages 216)))\n  book.title)','records.grhm') + p('Known mismatches produce <code>E111</code>; call-arity errors produce <code>E112</code>. Opaque JavaScript imports and external resource payloads remain unknown. There is no generic or explicit union annotation syntax.')),
        section('nulls','Handle missing values', p('A lookup such as <code>first</code> may return no value. Use <code>or-else</code> for a fallback, or <code>is-null</code>/<code>not-null</code> to refine a branch. These guards handle both null and undefined; <code>= null</code> is a strict comparison.') + code('(let ((first-price (first (arr 12 24))))\n  (if (not-null first-price)\n    (+ first-price 1)\n    0))\n\n(or-else (first (arr)) "Nothing here")','nulls.grhm')),
        section('matching','Conditionals and enums', p('Expression <code>if</code> returns one of two values. Use <code>cond</code> for multiple conditions and <code>match</code> for literal or enum cases. Enum matches are checked for exhaustiveness.') + code('(enum status open closed)\n\n(fn label (value)\n  (match value\n    ("open" "In progress")\n    ("closed" "Complete")\n    (else "Unknown")))','matching.grhm')),
        section('eval','Evaluate the pure core', code("npx grhm eval '(sum (arr 1 2 3))'\nnpx grhm repl",'terminal') + p('The evaluator includes project functions, enums, and translation catalogs. State, resources, JavaScript interop, and server operations require a compiled application.')),
      ]
    },
    data: {
      intro:'Read asynchronous data through resources. Send mutations through declared API routes, then refresh the values your interface consumes.',
      sections:[
        section('resources','Read a resource', p('A resource exposes <code>data</code>, <code>loading</code>, and <code>error</code>. Give list resources an empty default so a page can render before its first request finishes.') + code('(data\n  (resource notes "/api/notes" :default (arr)))\n\n(page "/" home\n  (v :gap 12\n    (when notes.loading (txt "Loading…"))\n    (each note notes.data (txt note.text))))','resource.grhm')),
        section('mutations','Send and refresh', p('<code>send</code> is checked against declared methods, routes, and input contracts. Keyword properties become the JSON body. Actions run in order, so the refresh follows the completed mutation.') + code('(btn "Save"\n  (click\n    (send post "/api/notes" :text draft)\n    (refresh notes)\n    (set draft "")))','mutation.grhm')),
        section('errors','Handle a failed action', p('Use <code>try</code>/<code>catch</code> around actions and show a toast when a request fails. Resource errors can also be rendered in the page.') + code('(btn "Save"\n  (click\n    (try\n      (send post "/api/notes" :text draft)\n      (refresh notes)\n      (catch\n        (toast "Could not save the note" :tone error)))))','errors.grhm')),
        section('live','Polling and live updates', p('<code>:poll</code> sets an interval in seconds. <code>:live true</code> subscribes to the generated server’s change feed and requires a server-backed app.') + code('(resource notes "/api/notes"\n  :default (arr)\n  :live true)','live.grhm') + p('Every database mutation triggers all live resources to refresh. Polling consumers that share a URL share one timer, using the fastest active interval.')),
        section('lifecycle','Request lifetime and caching', p('A refresh cancels a superseded request. Removing the last consumer stops polling and cancels pending work. Unused entries are retained for 30 seconds, with a cap of 128 unused URLs. Active resources stay cached, and late responses cannot overwrite newer data.')),
      ]
    },
    server: {
      intro:'Declare SQLite tables and HTTP routes alongside the interface. The compiler emits a standalone server using Node builtins.',
      sections:[
        section('tables','Tables and queries', p('Columns use <code>auto</code>, <code>string</code>, <code>number</code>, or <code>boolean</code>. The auto column is the integer primary key. Optional fields accept absence; defaults and indexes are part of the declaration.') + code('(db\n  (table notes\n    (id auto)\n    (text string)\n    (archived boolean :default false :indexed true))\n  (seed notes\n    (row :text "Read the language guide")))','database.grhm') + p('Select with <code>:where</code>, <code>:order</code>, <code>:limit</code>, and <code>:offset</code>. Conditions compile to parameterized SQL. Equality is null-safe. <code>contains</code> uses case-sensitive literal substring matching; percent signs and underscores are not wildcards.')),
        section('routes','API routes and input contracts', p('A handler is an expression over route parameters, <code>body</code>, functions, and declared server environment values. Input contracts reject missing, mistyped, and unknown fields before the handler runs.') + code('(api\n  (get "/api/notes" (select notes))\n  (post "/api/notes"\n    (input (text string))\n    (insert notes :text body.text)))','api.grhm') + p('Use <code>insert</code>, <code>update</code>, and <code>delete-row</code> for writes. Updates and deletes identify a row by <code>:id</code>. <code>tx</code> wraps a synchronous expression in a transaction.')),
        section('auth','Sessions and authentication', p('<code>(auth users)</code> synthesizes a users table and signup, login, logout, and current-user routes under <code>/api/auth/</code>. Passwords are hashed with scrypt; session cookies are HttpOnly and SameSite=Lax. A route with <code>:auth true</code> requires a session and exposes <code>user</code> to its handler.') + code('(auth users)\n\n(api\n  (get "/api/me" :auth true user))','auth.grhm') + p('The built-in flow supports email and password sessions. Roles, OAuth, email verification, and password reset are not included.')),
        section('jobs','Jobs and uploads', p('A job runs a server expression at an interval in seconds. Jobs run in one process and have no durable queue or retry policy.') + code('(db\n  (table heartbeats (id auto) (time number)))\n\n(job heartbeat :every 60\n  (insert heartbeats :time (now)))','job.grhm') + p('<code>(uploads :max-kb 2048)</code> enables file uploads. Bind a <code>file-input</code> to a string state with <code>:to</code>. Files are stored on local disk. The upload endpoint checks the mutation header but is not auth-gated.')),
        section('behavior','Server behavior and limits', list(['Unexpected API errors return a generic 500; diagnostic details remain in structured server logs. Intentional <code>fail</code> responses keep their status and message.','Mutations require the <code>x-grhm</code> header. The generated client supplies it.','Migrations add tables, columns, and indexes. Type changes and dropped columns require manual migration.','References are soft: the checker validates targets, but SQLite foreign-key enforcement and cascades are not enabled.','There are no SQL joins or aggregations. Nullable ordering uses SQL three-valued logic.']) + p('See the <a href="/examples#notes">notes example</a> for a complete database-to-interface application.')),
      ]
    },
    testing: {
      intro:'Keep interaction tests beside the program. GRHM lowers the same test declarations to unit tests and browser tests.',
      sections:[
        section('declare','Declare a test', p('Add a test block to an application with the counter page. Steps locate visible text or stable node IDs. Pure-expression assertions can call project functions.') + code('(tests\n  (test "counter increments"\n    (visit "/")\n    (click "Add one")\n    (expect-text "1"))\n  (test "arithmetic"\n    (expect-eq (+ 2 3) 5)))','tests.grhm')),
        section('unit','Run unit tests', p('The scaffold includes Vitest and jsdom. The unit suite renders the generated application; full-stack applications also start the generated API against an in-memory database.') + code('npx grhm test --unit','terminal')),
        section('browser','Run browser tests', p('Install the browser runner once in the application directory, then run both suites. Check the runner output: a missing runner is reported as skipped.') + code('npm install -D @playwright/test\nnpx playwright install chromium\nnpx grhm test','terminal')),
        section('steps','Available steps', p('<code>visit</code>, <code>click</code>, <code>fill</code>, <code>press</code>, <code>expect-text</code>, <code>expect-gone</code>, <code>expect-node</code>, <code>expect-count</code>, <code>expect-value</code>, <code>expect-url</code>, <code>expect-eq</code>, and <code>screenshot</code> are supported. Their arguments are listed in the <a href="/docs/reference#test-steps">test reference</a>.') + p('Screenshots become Playwright screenshot assertions and are skipped in jsdom. Record an initial baseline with Playwright’s update-snapshots option.')),
        section('check','Check before building', code('npx grhm check\nnpx grhm fmt --check\nnpx grhm build\nnpx tsc --noEmit','terminal') + p('The compiler validates shapes, references, routes, and known types. Run TypeScript explicitly to check generated output and JavaScript interop signatures; the Vite build transpiles and bundles the code.')),
      ]
    },
    tooling: {
      intro:'The compiler exposes structured information for editors and coding agents, including stable node IDs and atomic edits. The Working with agents guide walks through a complete edit.',
      sections:[
        section('diagnostics','Read structured diagnostics', p('Diagnostics include a stable code, severity, source span, and node ID where available. Expected and received values, property names, and suggestions give tools context for a repair.') + code('npx grhm check --json\nnpx grhm codes','terminal')),
        section('identity','Node IDs and revisions', p('Node IDs come from semantic keys, not source positions. They survive formatting and unrelated edits. For nodes targeted by frequent patches, assign an explicit <code>:id</code>.') + code('(grid :id "product-grid" :cols 4 :gap 16\n  (txt "Products"))','identity.grhm') + p('A project revision hashes canonical source across all included files. Formatting alone does not change the revision. Unnamed same-operation siblings can still shift occurrence-based IDs.')),
        section('patches','Apply an atomic patch', p('Read the current revision from the checker, then use it in a patch. The compiler validates the entire patched project before accepting the edit. A stale revision or invalid result leaves the source unchanged.') + code('(patch :revision "CURRENT_REVISION"\n  :target product-grid\n  (set cols 3))','change.grhm') + code('npx grhm patch change.grhm','terminal')),
        section('inspect','Inspect a program', code('npx grhm ast --json\nnpx grhm inspect --node product-grid\nnpx grhm reference','terminal') + p('The model-facing reference is generated from the operation registry. It can be included in a tool or model’s context without manually maintaining a parallel language specification.')),
        section('editors','Editor and compiler services', p('<code>grhm lsp</code> provides diagnostics, hover, completion, definition, references, rename, formatting, and suggestion-based quick fixes over stdio. <code>grhm serve</code> exposes the compiler through JSON lines.') + p('The repository includes a VS Code client in <code>editors/vscode/</code>. It has not yet been launch-tested in a real VS Code instance.')),
      ]
    },
    output: {
      intro:'GRHM emits conventional application code. The development server watches source files; the production build bundles the client.',
      sections:[
        section('development','Develop locally', code('npm run dev','terminal') + p('The development command recompiles included files and serves the client with Vite. For apps with a backend, it also starts the generated API server and connects the Vite proxy.')),
        section('files','Inspect generated files', table([['Output','Responsibility'],['App.tsx','History routing and lazy page loading'],['pages/*.tsx','React page components'],['state.ts','Shared application stores'],['components.tsx','Reusable components'],['lib.ts','Functions shared by client and server'],['helpers.ts','React-free runtime helpers'],['styles.css','Styles, theme tokens, and motion'],['server.ts','Generated API and SQLite server, when needed']]) + p('The generated server uses Node builtins and needs Node 22.13 or newer; Node 22.22+ or 24.15+ runs it without experimental flags. See the versions listed in <a href="/docs#requirements">getting started</a>.')),
        section('production','Build and run', code('npm run build\nnpm start','terminal') + p('For server-backed apps, <code>start</code> runs the generated server and serves the built <code>dist/</code> client with a history-route fallback. Frontend-only apps use Vite preview; their built assets can be served by a static host.')),
        section('configuration','Configure the server', table([['Variable','Purpose'],['PORT','HTTP listen port'],['GRHM_DB','SQLite database path'],['GRHM_UPLOADS','Upload directory'],['GRHM_SECURE=1','Set Secure on session cookies'],['GRHM_CORS_ORIGIN','Allow a specific cross-origin client'],['GRHM_SESSION_DAYS','Session lifetime; defaults to 30 days']]) + p('Use persistent storage for the database and upload directory. Never enable <code>GRHM_TEST_HOOKS</code> in a deployed application. The scaffold also includes a Dockerfile.')),
        section('ownership','Working with the output', p('Generated code can be inspected and maintained with ordinary TypeScript and React tools. If you continue compiling GRHM, keep custom code in source files or imported modules; the compiler replaces generated files on each build.')),
      ]
    },
    about: {
      intro:'GRHM (pronounced “Graham”) stands for Generative Reactive Hypermedia Metalanguage. This is the v0.2 reference implementation.',
      sections:[
        section('purpose','Why GRHM exists', p('GRHM gives developers and code-generating tools a compact representation of a web application. A shared schema, structured diagnostics, stable identities, and revision-checked patches make changes explicit and verifiable.')),
        section('implemented','What is implemented', p('The implementation includes a functional core, React interface generation, SQLite-backed APIs, sessions, resources, live updates, jobs, uploads, internationalization, testing, a CLI, and an editor protocol. The compiler emits readable code and rejects known invalid programs before generation.')),
        section('limits','Current limits', list(['Types are inferred across known values; opaque interop and external data remain unknown.','Database migrations are additive. SQL joins, cascades, and enforced foreign keys are not available.','Jobs and uploads use one server process and local storage.','Authentication supports email/password sessions, without roles or identity providers.','Live changes refresh every live resource, rather than subscribing by table.','Translation catalogs have template parameters, without pluralization or lazy catalog loading.','The editor client and screenshot baselines still require verification in their target environments.'])),
        section('stability','Stability', p('The project is pre-1.0. Stable surfaces include the form vocabulary, diagnostic codes, node identity rules, patch protocol, and generated-file layout. Breaking language or diagnostic changes use a minor version bump before 1.0.')),
      ]
    }
  };
}
function table(rows) { return `<div class="table-scroll"><table><thead><tr>${rows[0].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(row=>`<tr>${row.map((c,i)=>`<td>${i===0?inline(c):c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
function sidebar(slug) {
  let group = '';
  return `<nav aria-label="Documentation">${pages.map(([id,title,section])=>{const label = group !== section ? `<h2>${section}</h2>` : ''; group=section; return `${label}<a href="${href(id)}" ${id===slug?'aria-current="page"':''}>${title}</a>`;}).join('')}</nav>`;
}
let referencePromise;
async function referenceArticle(escape, code) {
  referencePromise ??= fetch('/reference.json').then(r=>{if(!r.ok)throw new Error('Reference unavailable');return r.json();});
  const r = await referencePromise;
  const groups = new Map();
  for (const op of r.ops) { if(!groups.has(op.category))groups.set(op.category,[]); groups.get(op.category).push(op); }
  const type = spec => spec.kind === 'enum' ? (spec.values??[]).join(' | ') : spec.kind;
  const item = (name,description,detail='') => `<details class="reference-item" data-search="${escape(name+' '+description).toLowerCase()}"><summary><code>${escape(name)}</code><span>${escape(description)}</span></summary><div>${detail || p('Use this form inside its declared context.')} </div></details>`;
  const sections = [...groups].map(([category,ops]) => section(category.toLowerCase().replace(/\W+/g,'-'), category.charAt(0).toUpperCase()+category.slice(1), ops.map(op=>item([op.name,...op.aliases].join(' / '),op.doc,
    code(`(${op.name}${op.positional.length?' '+op.positional.map(p=>p.name+(p.variadic?'…':p.required?'':'?')).join(' '):''}${Object.keys(op.props).length?' '+Object.entries(op.props).map(([name,spec])=>'[:'+name+' '+type(spec)+']').join(' '):''}${op.children==='elements'?' …':''})`,'shape') + (op.aliases.length?p('Aliases: '+op.aliases.map(inline).join(', ')):'') + (Object.keys(op.props).length?table([['Property','Accepted value'],...Object.entries(op.props).map(([n,t])=>[':'+escape(n),escape(type(t))])]):'') + (op.styled?p('Accepts the shared <a href="#styles">style properties</a>.'):''))).join('')));
  sections.push(section('special-forms','Functions and actions',(r.specialForms??[]).map(spec=>item(spec.name,spec.doc)).join('')));
  sections.push(section('expressions','Expressions',Object.entries(r.expressions).map(([name,spec])=>item(name,spec.doc??`(${name}${' x'.repeat(spec.minArity)}${spec.maxArity===undefined?' …':''})`,p(`Arguments: ${spec.minArity}${spec.maxArity===spec.minArity?'':spec.maxArity===undefined?' or more':'–'+spec.maxArity}.`))).join('')));
  sections.push(section('server-operations','Server operations',Object.entries(r.server).map(([name,spec])=>item(name,spec.doc)).join('')));
  sections.push(section('styles','Style properties',table([['Property','Accepted value'],...Object.entries(r.styles).map(([n,t])=>[':'+escape(n),escape(type(t))])])));
  sections.push(section('motion','Motion properties',table([['Property','Accepted value'],...Object.entries(r.motion).map(([n,t])=>[':'+escape(n),escape(type(t))])])));
  sections.push(section('test-steps','Test steps',Object.entries(r.tests).map(([n,s])=>item(n,s.doc??'Test step',code(`(${n} ${s.args.join(' ')})`,'shape'))).join('')));
  sections.push(section('diagnostics','Diagnostic codes',Object.entries(r.diagnostics).map(([n,d])=>item(n,d)).join('')));
  return {intro:'Operation signatures, properties, and diagnostic codes generated directly from the compiler’s schema.', lead:'<label class="reference-search"><span>Find a form or diagnostic</span><input type="search" id="reference-search" placeholder="Try resource, map, or E111" autocomplete="off"></label><p class="search-empty" hidden>No matching forms or diagnostics. Try another name.</p>', sections};
}
function renderExamples({root,header,footer,code,escape,arrow}) {
  document.title='Examples — GRHM';
  document.querySelector('meta[name="description"]').content='Complete GRHM applications for state, functions, and SQLite-backed APIs.';
  root.innerHTML=header('examples')+`<main id="main" class="examples-page wrap"><h1>Example applications.</h1><p class="page-intro">Start with state, add a function, or connect a database. Each example is a complete, compiler-checked application.</p><nav class="example-nav" aria-label="Examples">${examples.map(e=>`<a href="#${e.id}">${e.title} ${arrow}</a>`).join('')}</nav>${examples.map(e=>`<section class="example-section" id="${e.id}"><div><h2>${e.title}</h2><p>${e.description}</p><a class="text-link" download="${e.id}.grhm" href="/examples/${e.id}.grhm">Download source ${arrow}</a></div>${code(e.source,e.id+'.grhm')}</section>`).join('')}<div class="example-end"><p>Save an example as <code>app.grhm</code> in a scaffolded project, then run <code>npm run dev</code>.</p><a class="text-link" href="/docs">Set up a project ${arrow}</a></div></main>`+footer();
}
export async function renderContent(api) {
  const {root,header,footer,code,escape,arrow}=api;
  if(location.pathname==='/examples'){renderExamples(api);return;}
  const slug = location.pathname.replace(/^\/docs\/?/,'').replace(/\/$/,'');
  const entry=pages.find(([id])=>id===slug);
  if(!location.pathname.startsWith('/docs')||!entry){document.title='Page not found — GRHM';root.innerHTML=header()+`<main class="wrap not-found" id="main"><h1>Page not found.</h1><p>This address does not match a documentation page.</p><a class="button primary" href="/docs">Open the documentation ${arrow}</a></main>`+footer();return;}
  const article = slug==='reference' ? await referenceArticle(escape,code) : articles(code)[slug];
  if (api.isCurrent && !api.isCurrent()) return;
  document.title=entry[1]+' — GRHM';
  document.querySelector('meta[name="description"]').content=article.intro;
  const index=pages.indexOf(entry),prev=pages[index-1],next=pages[index+1];
  root.innerHTML=header('docs')+`<div class="docs-layout"><aside class="docs-sidebar">${sidebar(slug)}</aside><main class="doc-article" id="main" tabindex="-1"><details class="mobile-docs"><summary>Documentation menu</summary>${sidebar(slug)}</details><h1>${entry[1]}</h1><p class="doc-intro">${article.intro}</p>${article.lead??''}${article.sections.map(s=>`<section id="${s.id}" class="doc-section"><h2><a href="#${s.id}">${s.title}</a></h2>${s.body}</section>`).join('')}<nav class="doc-pagination" aria-label="Next and previous pages">${prev?`<a href="${href(prev[0])}"><span>Previous</span>${prev[1]}</a>`:'<span></span>'}${next?`<a href="${href(next[0])}"><span>Next</span>${next[1]} ${arrow}</a>`:''}</nav></main><aside class="doc-toc"><nav aria-label="On this page"><h2>On this page</h2>${article.sections.map(s=>`<a href="#${s.id}">${s.title}</a>`).join('')}${slug==='reference'?'<a class="reference-download" href="/language-reference.txt" download>Download plain text</a>':''}</nav></aside></div>`+footer();
  document.querySelector('#reference-search')?.addEventListener('input',event=>{
    const query=event.target.value.trim().toLowerCase();let matches=0;
    document.querySelectorAll('[data-search]').forEach(item=>{item.hidden=!item.dataset.search.includes(query);if(!item.hidden)matches++;});
    document.querySelectorAll('.doc-section').forEach(section=>{if(section.querySelector('[data-search]'))section.hidden=!section.querySelector('[data-search]:not([hidden])');else{section.hidden=!!query&&!section.textContent.toLowerCase().includes(query);if(!section.hidden)matches++;}});
    document.querySelector('.search-empty').hidden=matches>0;
  });
}
